# Writes JvmFuncsFallbacks.c like mx_substratevm.py's JvmFuncsFallbacksBuildTask
#
# usage: jvm-fallbacks.py <symbol list> <out.c>
import sys

PLAIN = {"JVM_GC", "JVM_ActiveProcessorCount", "JVM_GetInterfaceVersion", "JVM_GetManagement",
         "JVM_IsSupportedJNIVersion", "JVM_MaxObjectInspectionAge", "JVM_NativePath", "JVM_ReleaseUTF",
         "JVM_SupportsCX8", "JVM_BeforeHalt", "JVM_Halt", "JVM_LoadLibrary", "JVM_UnloadLibrary",
         "JVM_FindLibraryEntry", "JVM_FindSignal", "JVM_RaiseSignal", "JVM_RegisterSignal", "JVM_FreeMemory",
         "JVM_MaxMemory", "JVM_TotalMemory", "JVM_RawMonitorCreate", "JVM_RawMonitorDestroy",
         "JVM_RawMonitorEnter", "JVM_RawMonitorExit"}

out = ["/* Fallback implementations autogenerated like mx_substratevm.py */", "",
       "#include <stdio.h>", "#include <stdlib.h>", "#include <jni.h>", ""]
for name in open(sys.argv[1]).read().split():
    if name in PLAIN:
        out.append('JNIEXPORT void JNICALL %s() {\n    fprintf(stderr, "%s called:  Unimplemented\\n");\n    abort();\n}\n' % (name, name))
    else:
        out.append('JNIEXPORT jobject JNICALL %s(JNIEnv *env) {\n    (*env)->FatalError(env, "%s called:  Unimplemented");\n    return NULL;\n}\n' % (name, name))
open(sys.argv[2], "w").write("\n".join(out))
